package com.projectkorra.projectkorra.prediction.rollback;

import com.projectkorra.projectkorra.prediction.rollback.world.RollbackNativeItems.Kind;
import java.util.Map;

/**
 * Reads the Paper API's metadata categories generated by the paperweight build.
 * The session sends this catalog to the client so
 * both platforms expose the same common metadata subtype for dynamically created items.
 */
public final class PaperRollbackItemCatalog {
    private PaperRollbackItemCatalog() { }
    public static Map<String, Kind> capture() {
        return PaperItemMetadata.VALUES;
    }
}
